    protected void onStart() {
        super.onStart();
        TextView ScheduleInfo = (TextView) findViewById(R.id.ScheduleInfo);

        String trainingTypeName = ActiveSchedule.getTrainingsType() != null ? ActiveSchedule.getTrainingsType().name() : "not set";
        String scheduleInfo = String.format(getResources().getString(R.string.ScheduleInfo), ActiveSchedule.getRepetitions(), ActiveSchedule.getPauseTime(), ActiveSchedule.getSets(), ActiveSchedule.getSpeed(), trainingTypeName);
        ScheduleInfo.setText(scheduleInfo);
    }

    @Override
    protected void onStop() {
        super.onStop();
    }

    @Override
    protected void onSaveInstanceState(Bundle state) {
        super.onSaveInstanceState(state);
        state.putSerializable("scheduleName", ActiveSchedule.getName());
    }

    public void addExcersize() {
